// ==============================
// n8n - Code in JavaScript
// Generador de Portafolio HTML (CSS embebido)
// Output esperado: { html: "<!DOCTYPE html>..." }
// ==============================

// 1) Lee el input (Webhook / nodo anterior)
const data = $input.first()?.json ?? {};

// 2) Helpers
function safeJsonParse(value, fallback) {
  if (value === undefined || value === null) return fallback;

  // Ya viene como array u objeto
  if (Array.isArray(value)) return value;
  if (typeof value === 'object') return value;

  // Si no es string, no podemos parsear
  if (typeof value !== 'string') return fallback;

  const trimmed = value.trim();
  if (!trimmed) return fallback;

  try {
    return JSON.parse(trimmed);
  } catch {
    return fallback;
  }
}

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function toArrayFromCommaString(value, fallbackCsv) {
  const raw = (value ?? fallbackCsv);
  if (Array.isArray(raw)) return raw.map(x => String(x).trim()).filter(Boolean);

  return String(raw)
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

// 3) Campos simples
const nombre = (data.nombre ?? 'Tu Nombre').toString();
const profesion = (data.profesion ?? 'Tu Profesión').toString();
const resumen = (data.resumen ?? 'Resumen breve de tu perfil.').toString();

// Skills puede venir como string "A, B, C" o array
const skills = toArrayFromCommaString(data.skills, 'HTML, CSS, JavaScript');

// 4) Proyectos y links pueden venir como JSON string o array
// Proyectos esperados: [{ titulo, descripcion, link }]
// Links esperados: [{ texto, url }]
const proyectos = safeJsonParse(data.proyectos, []);
const links = safeJsonParse(data.links, []);

// 5) Render Skills
const skillsHtml = skills
  .map(s => `<span class="chip">${escapeHtml(s)}</span>`)
  .join('');

// 6) Render Proyectos
let proyectosHtml = '';
if (Array.isArray(proyectos) && proyectos.length) {
  proyectosHtml = proyectos.map(p => {
    const titulo = escapeHtml(p?.titulo || 'Proyecto');
    const descripcion = escapeHtml(p?.descripcion || '');
    const link = String(p?.link || '').trim();
    const linkSafe = escapeHtml(link);

    const linkHtml = link
      ? `<a class="btn" href="${linkSafe}" target="_blank" rel="noopener">Ver proyecto</a>`
      : '';

    return `
      <div class="card">
        <h4>${titulo}</h4>
        <p>${descripcion}</p>
        ${linkHtml}
      </div>
    `;
  }).join('');
} else {
  proyectosHtml = `<p class="muted">No hay proyectos aún.</p>`;
}

// 7) Render Links
let linksHtml = '';
if (Array.isArray(links) && links.length) {
  linksHtml = links.map(l => {
    const texto = escapeHtml(l?.texto || 'Link');
    const url = String(l?.url || '#').trim();
    const urlSafe = escapeHtml(url || '#');
    return `<li><a href="${urlSafe}" target="_blank" rel="noopener">${texto}</a></li>`;
  }).join('');
} else {
  linksHtml = `<li class="muted">No hay links aún.</li>`;
}

// 8) CSS embebido
const css = `
body{font-family:Arial,sans-serif;background:#0b1220;color:#e6eaf2;margin:0;padding:30px}
.container{max-width:980px;margin:0 auto}
.hero{padding:26px;border-radius:16px;background:linear-gradient(180deg,rgba(56,189,248,.12),rgba(17,24,39,.6));border:1px solid rgba(148,163,184,.18)}
h1{margin:0;font-size:42px}
h2{margin:8px 0 0;color:#a8b3cf;font-weight:500}
.section{margin-top:18px;padding:18px;border-radius:14px;border:1px solid rgba(148,163,184,.18);background:rgba(15,23,42,.6)}
.section h3{margin:0 0 12px}
.chip{display:inline-block;padding:8px 12px;border-radius:999px;border:1px solid rgba(148,163,184,.2);margin:0 8px 8px 0}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
.card{padding:14px;border-radius:14px;border:1px solid rgba(148,163,184,.18);background:rgba(2,6,23,.45)}
.card h4{margin:0 0 6px}
.card p{margin:0 0 10px;color:#cbd5e1}
.btn{display:inline-block;padding:8px 12px;border-radius:10px;border:1px solid rgba(56,189,248,.35);text-decoration:none;color:#dbeafe}
ul{margin:0;padding-left:18px}
a{color:#7dd3fc}
.muted{color:#9aa6bf}
.footer{margin-top:14px;color:#9aa6bf;font-size:13px}
`;

// 9) HTML final
const finalHtml = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Portafolio - ${escapeHtml(nombre)}</title>
  <style>${css}</style>
</head>
<body>
  <div class="container">
    <div class="hero">
      <h1>${escapeHtml(nombre)}</h1>
      <h2>${escapeHtml(profesion)}</h2>
    </div>

    <div class="section">
      <h3>Resumen</h3>
      <p>${escapeHtml(resumen)}</p>
    </div>

    <div class="section">
      <h3>Skills</h3>
      <div>${skillsHtml}</div>
    </div>

    <div class="section">
      <h3>Proyectos</h3>
      <div class="grid">${proyectosHtml}</div>
    </div>

    <div class="section">
      <h3>Links</h3>
      <ul>${linksHtml}</ul>
    </div>

    <div class="footer">Generado automáticamente con n8n.</div>
  </div>
</body>
</html>`;

// 10) Retorna como string plano en "html"
return [
  {
    html: finalHtml
  }
];
